CREATE TABLE purchase_account_binding (player_id TEXT PRIMARY KEY REFERENCES player(id), google_account_id TEXT NOT NULL UNIQUE, apple_account_token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE purchase_ledger (purchase_key TEXT PRIMARY KEY, platform TEXT NOT NULL CHECK(platform IN('google','apple')), transaction_id TEXT NOT NULL, player_id TEXT NOT NULL REFERENCES player(id), product_id TEXT NOT NULL, receipt_hash TEXT NOT NULL, quantity INTEGER NOT NULL, environment TEXT NOT NULL, verification_source TEXT NOT NULL, facts_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'verified_pending' CHECK(status IN('verified_pending','granted','revoked')), operation_id TEXT, save_version INTEGER, created_at INTEGER NOT NULL, granted_at INTEGER, UNIQUE(platform,transaction_id));
CREATE TABLE purchase_entitlement (player_id TEXT NOT NULL REFERENCES player(id), key TEXT NOT NULL, value TEXT NOT NULL, source_key TEXT NOT NULL REFERENCES purchase_ledger(purchase_key), PRIMARY KEY(player_id,key));
CREATE INDEX purchase_ledger_player ON purchase_ledger(player_id,created_at DESC);
